import math
from pprint import pprint
from elasticsearch import Elasticsearch, exceptions

from utils.util import call_api
from utils.log_util import logger
from config.config import API_URL, ES_CONFIG
from utils.query_util import build_weighted_keywords

def fetch_data(query, kbBaseIds, logger, method, **kwargs):
    data = {}
    if method == 'ES':
        return fetch_data_es(query, kbBaseIds, logger, **kwargs)

    # ----------------- #
    # API call for NODE #
    # ---------------- #
    elif method == 'NODE':
        data['text'] = query
        data['parentKbIds'] = kbBaseIds
        data['queryMode'] = 3
        data['querySize'] = 10
        data['blockType'] = []
        data['qaType'] = []
    # --------------------- #
    # API call for RELATION #
    # --------------------- #
    elif method == 'RELATION':
        data['text'] = query
        data['parentKbIds'] = kbBaseIds
        data['queryMode'] = 3
        data['querySize'] = 10
        data['blockType'] = []
        data['qaType'] = []
    elif method == 'GDB':
        data['nodeResourceId'] = kwargs['nodeResourceId']
        data['kbBaseId'] = kbBaseIds[0]
    else:
        return None

    response = call_api(kwargs['URL'][method], data=data, logger=logger)

    ret = wrapper_response(response, method)

    return ret

def calculate_score(score: float, node_name: str, node_level: int) -> float:
    """根据自定义公式计算最终得分。

    参数:
        score (float): Elasticsearch匹配查询返回的原始得分。
        node_name (str): 要计算得分的节点名称。
        node_level (int): 调整得分的节点级别。

    返回:
        float: 最终的自定义得分。
    """
    node_length = len(node_name)
    # 根据公式计算调整后的得分
    final_score = score * math.sqrt(node_level / node_length)
    return final_score

def is_node_in_query(node_key_word_list, query_text: str) -> bool:
    for key_word in node_key_word_list:
        if key_word in query_text:
            return True

def fetch_data_es(query, kbBaseIds, logger, size=10, **kwargs):
    es_client = Elasticsearch(
        hosts=kwargs['ES_HOST'],
        http_auth=(kwargs['ES_USER_NAME'], kwargs['ES_PASSWORD']),
        port=kwargs['ES_PORT']
    )
    if not es_client.ping():
        logger.info("Failed connected to Elasticsearch!")
        return None
    logger.info("Successfully connected to Elasticsearch!")
    query_body = construct_query_body(query, kbBaseIds)
    response = es_client.search(index=kwargs['ES_INDEX'], body=query_body, size=size*5)
    hits = response.get('hits', {}).get('hits', [])
    for hit in hits:
        node_name = hit['_source']['nodeName']
        node_level = hit['_source']['nodeLevel'] + 1
        related_tree_node_list = [relatedTreeNode['nodeName'] for relatedTreeNode in hit['_source']['relatedTreeNodeList']]
        node_key_word_list = hit['_source'].get('nodeKeyWordList', []) + related_tree_node_list
        score = hit['_score']

        custom_score = calculate_score(score, node_name, node_level)
        if (query == node_name) or (query in node_key_word_list) or (is_node_in_query(node_key_word_list, query)):
            custom_score = custom_score * 6
        elif (query in node_name) or (node_name in query):
            custom_score = custom_score * 3
        hit['_score'] = custom_score  # 使用自定义得分覆盖Elasticsearch的默认得分
    # 按自定义得分降序排序命中
    sorted_hits = sorted(hits, key=lambda x: x['_score'], reverse=True)
    return {
        'hits':
        {
            'hits': sorted_hits[:size]
        }
    }

def construct_query_body(query, kbBaseIds):
    weighted_keywords = build_weighted_keywords(query, mode='all', lang='zh')
    fields = ['nodeName^3', 'nodeKeyWordList']

    # 如果knowledgeBaseId是单个值或需要特定术语匹配，则使用term查询
    knowledge_base_clauses = [
        {
            "term": {
                "knowledgeBaseId": knowledge_base_id
            }
        }
        for knowledge_base_id in kbBaseIds
    ]

    if len(weighted_keywords) > 0:
        # 初始化should子句列表
        should_clauses = []

        # 任务1：为每个关键词创建一个multi_match查询
        for idx, weighted_keyword in enumerate(weighted_keywords):
            should_clauses.append({
                "multi_match": {
                    "query": weighted_keyword['word'],
                    "fields": fields,
                    "boost": weighted_keyword.get('boost', 1) * len(weighted_keyword['word'])
                }
            })

        # 任务2和3：构建Elasticsearch查询主体
        query_body = {
            "query": {
                "bool": {
                    "should": should_clauses,
                    "minimum_should_match": min(1, len(weighted_keywords)),
                    "must": [
                        {
                            "bool": {
                                "should": knowledge_base_clauses,
                                "minimum_should_match": 1
                            }
                        }
                    ]
                }
            }
        }
    else:
        query_body = {
            "query": {
                "bool": {
                    "must": [
                        {
                            "multi_match": {
                                "query": query,
                                "fields": fields
                            }
                        }
                    ],
                    "should": knowledge_base_clauses,
                    "minimum_should_match": 1
                }
            }
        }

    return query_body

def wrapper_response(response, method):
    ret = {}
    if method == 'ES':
        """
        核心字段：
        1. nodeName
        2. nodeUid
        3. nodeLevel
        4. score
        5. parentKbIds
        """
        hits = response.get('hits', {}).get('hits', [])
        hits = [
            {
                'nodeName': hit.get('_source', {}).get('nodeName', ''),
                'nodeUid': hit.get('_source', {}).get('nodeUid', ''),
                'nodeLevel': hit.get('_source', {}).get('nodeLevel', ''),
                'score':hit.get('_source', {}).get('score', ''),
                'parentKbIds': hit.get('_source', {}).get('parentKbIds', [])
            }
            for hit in hits
        ]
        ret['resultList'] = hits

    elif method == 'NODE':
        """
        核心字段：
        1. similarity：相似度进行阶段
        2. nodeUid
        3. nodeName
        4. knowledgeBaseId
        """
        resultList = response.get('data', {}).get('resultList', [])
        resultList = [
            {
                'similarity': result.get('similarity', ''),
                'nodeUid': result.get('nodeUid', ''),
                'nodeName': result.get('nodeName', ''),
                'knowledgeBaseId': result.get('knowledgeBaseId', ''),
            }
            for result in resultList
        ]
        ret['resultList'] = resultList
    elif method == 'RELATION':
        """
        核心字段：
        1. similarity：相似度进行阶段
        2. fromNodeName：起始节点
        3. toNodeName：终止节点
        4. relationEn
        """
        resultList = response.get('data', {}).get('resultList', [])
        resultList = [
            {
                'similarity': result.get('similarity', ''),
                'fromNodeName': result.get('fromNodeName', ''),
                'toNodeName': result.get('toNodeName', ''),
                'relationEn': result.get('relationEn', ''),
            }
            for result in resultList
        ]
        ret['resultList'] = resultList
    else:
        knowledgeList = response.get('data', {}).get('knowledgeList', [])
        knowledgeList = [
            {
                'nodeUid': knowledge.get('nodeUid', ''),
                'nodeName': knowledge.get('nodeName', ''),
                'clusterTitle': knowledge.get('clusterTitle', ''),
            }
            for knowledge in knowledgeList
        ]

        knowledgeRelationDtoList = response.get('data', {}).get('knowledgeRelationDtoList', [])
        knowledgeRelationDtoList = [
            {
                'relationName': knowledge.get('relationName', ''),
                'fromNodeId：': knowledge.get('fromNodeId：', ''),
                'toNodeId：': knowledge.get('toNodeId：', ''),
            }
            for knowledge in knowledgeRelationDtoList
        ]
        ret['knowledgeList'] = knowledgeList
        ret['knowledgeRelationDtoList'] = knowledgeRelationDtoList
    return ret

